def transform_v12(grid):
    from collections import Counter
    g = [r[:] for r in grid]
    h, w = len(g), len(g[0])
    bg = Counter(x for r in g for x in r).most_common(1)[0][0]

    two_rows = [i for i in range(h) if all(x==2 for x in g[i])]
    two_cols = [j for j in range(w) if all(g[i][j]==2 for i in range(h))]
    obj = [(i,j) for i in range(h) for j in range(w) if g[i][j] not in (bg, 2)]

    obj_vals = {}
    for i,j in obj:
        obj_vals[(i,j)] = g[i][j]

    if two_rows:
        max_obj_row = max(i for i,j in obj)
        marker_row = max_obj_row + 1
        if 0 <= marker_row < h:
            g[marker_row] = [8] * w

    elif two_cols:
        t = max(two_cols)
        min_obj_col = min(j for i,j in obj)
        max_obj_col = max(j for i,j in obj)

        dx = t + 1 - min_obj_col

        for i,j in obj:
            g[i][j] = bg

        for i,j in obj:
            nc = j + dx
            if 0 <= nc < w:
                g[i][nc] = obj_vals[(i,j)]

        marker_col = max_obj_col + dx + 1
        if 0 <= marker_col < w:
            for i in range(h):
                g[i][marker_col] = 8
        elif marker_col <= w:
            max_valid_obj_col = -1
            for i,j in obj:
                nc = j + dx
                if 0 <= nc < w:
                    if nc > max_valid_obj_col:
                        max_valid_obj_col = nc
            if max_valid_obj_col >= 0:
                marker_col = max_valid_obj_col + 1
                if 0 <= marker_col < w:
                    for i in range(h):
                        g[i][marker_col] = 8

    return g

